on conflict (provider, provider_code, (coalesce(period_num, 0))) do update set
  country_codes = excluded.country_codes, networks = excluded.networks, networks_by_country = excluded.networks_by_country,
  covers_rodrigues = excluded.covers_rodrigues, wholesale_usd_micros = excluded.wholesale_usd_micros,
  fup_policy = excluded.fup_policy, ip_export = excluded.ip_export, topup_supported = excluded.topup_supported, available = true,
  retail_eur_cents = case when public.esim_plans.retail_locked then public.esim_plans.retail_eur_cents else excluded.retail_eur_cents end;

